mapper.select:
SELECT a.vhcl_sn , a.ownr_nm , a.mt_id , a.anls_dt , a.bgng_dt , a.end_dt , a.chck_stts , a.chck_cd , c.chck_nm , c.msg_cn FROM anls_vhcl_chck_hstry a LEFT JOIN cmm_vhcl_chck_info c ON a.chck_cd = c.chck_cd WHERE 1=1 AND vhcl_sn = #{vhclSn} AND anls_dt BETWEEN CONCAT(#{searchDate}, ' 00:00:00') AND CONCAT(#{searchDate}, ' 23:59:59')
and ownr_nm = #{currentOwnrNm}
ORDER BY anls_dt
